// Zip files are generated by tools/generate-wsc-zips.js and committed
// directly under daylight/gallery/sports/wsc-2026/<day>/matches/<match>/download.zip,
// so Netlify serves them as static files — no external hosting needed.
const SITE_URL = "https://nocharte.com";
const WSC_BASE_PATH = "daylight/gallery/sports/wsc-2026";

// day-06/villanos-vs-domilquince -> safe, matches how the frontend builds it
const MATCH_KEY_PATTERN = /^day-\d{2}\/[a-z0-9-]+$/;

exports.handler = async function (event) {
  if (event.httpMethod !== "POST") {
    return {
      statusCode: 405,
      body: JSON.stringify({ message: "Method not allowed" }),
    };
  }

  try {
    const { matchKey, matchLabel, pin, email } = JSON.parse(event.body || "{}");

    if (!matchKey || !pin || !email) {
      return {
        statusCode: 400,
        body: JSON.stringify({ message: "Missing email, PIN, or match." }),
      };
    }

    if (!MATCH_KEY_PATTERN.test(matchKey)) {
      return {
        statusCode: 400,
        body: JSON.stringify({ message: "Invalid match." }),
      };
    }

    const wscPin = process.env.WSC_PIN;

    if (!wscPin) {
      return {
        statusCode: 500,
        body: JSON.stringify({ message: "Download access is not configured." }),
      };
    }

    if (String(pin).trim() !== String(wscPin).trim()) {
      return {
        statusCode: 401,
        body: JSON.stringify({ message: "Incorrect PIN." }),
      };
    }

    const zipUrl = `${SITE_URL}/${WSC_BASE_PATH}/${matchKey}/download.zip`;
    const title = matchLabel ? `WSC — ${matchLabel}` : "WSC Tournament";

    const zipCheck = await fetch(zipUrl, { method: "HEAD" });

    if (!zipCheck.ok) {
      return {
        statusCode: 404,
        body: JSON.stringify({ message: "Download link is not ready for this match yet." }),
      };
    }

    const resendApiKey = process.env.RESEND_API_KEY;
    const fromEmail = process.env.NOCHARTE_FROM_EMAIL || "NOCHARTE <onboarding@resend.dev>";

    if (!resendApiKey) {
      return {
        statusCode: 500,
        body: JSON.stringify({ message: "Email service is not configured." }),
      };
    }

    const emailHtml = `
      <div style="background:#f6f7fb;padding:40px 20px;font-family:Arial,sans-serif;color:#080b12;">
        <div style="max-width:560px;margin:0 auto;background:#ffffff;border:1px solid rgba(0,160,210,.16);border-radius:24px;padding:34px;">
          <p style="letter-spacing:3px;text-transform:uppercase;color:#2fa8ff;font-size:12px;font-weight:900;margin:0 0 18px;">
            NOCHARTE DAYLIGHT
          </p>

          <h1 style="font-size:28px;line-height:1.15;margin:0 0 18px;color:#080b12;">
            Your match photos are ready
          </h1>

          <p style="font-size:16px;line-height:1.6;color:#3a3f4a;margin:0 0 24px;">
            Your photo folder for <strong>${title}</strong> is ready.
          </p>

          <a href="${zipUrl}" target="_blank" style="display:inline-block;background:linear-gradient(90deg,#00d9ff,#2fa8ff,#8b3dff);color:#ffffff;text-decoration:none;padding:15px 26px;border-radius:999px;font-weight:bold;letter-spacing:.5px;">
            Download ZIP
          </a>

          <p style="font-size:13px;line-height:1.6;color:#7a8090;margin:28px 0 0;">
            If the button does not work, copy and paste this link into your browser:<br>
            <span style="color:#3a3f4a;">${zipUrl}</span>
          </p>

          <p style="font-size:12px;color:#a0a5b0;margin:32px 0 0;">
            NOCHARTE — CAPTURED IN DAYLIGHT
          </p>
        </div>
      </div>
    `;

    const resendResponse = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${resendApiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        from: fromEmail,
        to: [email],
        subject: `Your NOCHARTE Daylight photos are ready — ${title}`,
        html: emailHtml,
      }),
    });

    const resendData = await resendResponse.json();

    if (!resendResponse.ok) {
      return {
        statusCode: 500,
        body: JSON.stringify({
          message: "Email could not be sent.",
          details: resendData,
        }),
      };
    }

    return {
      statusCode: 200,
      body: JSON.stringify({
        message: "Download link sent successfully.",
      }),
    };
  } catch (error) {
    return {
      statusCode: 500,
      body: JSON.stringify({
        message: "Server error.",
        error: error.message,
      }),
    };
  }
};
